package in.recallradar;
import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Service @Transactional class DemoDataService {
 private final TenantService tenants; private final InventoryService inventory; private final ProductionService production; private final IncidentService incidents; private final RecallService recalls; private final AppProperties props; private final FinishedProductRepository products; private final RecipeRepository recipes; private final ProductionBatchRepository batches; private final IncidentRepository incidentRepo; private final RecallCaseRepository recallRepo; private final InventoryLotRepository lots;
 DemoDataService(TenantService t,InventoryService i,ProductionService p,IncidentService in,RecallService re,AppProperties pr,FinishedProductRepository fp,RecipeRepository rp,ProductionBatchRepository bp,IncidentRepository ir,RecallCaseRepository rr,InventoryLotRepository l){tenants=t;inventory=i;production=p;incidents=in;recalls=re;props=pr;products=fp;recipes=rp;batches=bp;incidentRepo=ir;recallRepo=rr;lots=l;}
 DemoSeedResponse seed(Membership member,DemoSeedRequest request){tenants.requireAdmin(member);if(!props.setupCode().equals(request.setupCode()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"The demo seed code is invalid.");var org=member.organizationId;var locs=tenants.locations(member);var kitchen=locs.stream().filter(x->x.name().equals("Demo Central Kitchen")).findFirst().orElseGet(()->tenants.createLocation(member,new LocationRequest("Demo Central Kitchen",LocationType.CENTRAL_KITCHEN,"Hyderabad")));var warehouse=locs.stream().filter(x->x.name().equals("Demo Warehouse")).findFirst().orElseGet(()->tenants.createLocation(member,new LocationRequest("Demo Warehouse",LocationType.WAREHOUSE,"Hyderabad")));var ss=tenants.suppliers(member);var dairy=ss.stream().filter(x->x.name().equals("Demo Fresh Dairy")).findFirst().orElseGet(()->tenants.createSupplier(member,new SupplierRequest("Demo Fresh Dairy","Ravi Kumar","dairy-demo@example.com","9000000001")));var farms=ss.stream().filter(x->x.name().equals("Demo Green Farms")).findFirst().orElseGet(()->tenants.createSupplier(member,new SupplierRequest("Demo Green Farms","Meera Shah","farms-demo@example.com","9000000002")));var is=tenants.ingredients(member);var curd=is.stream().filter(x->x.name().equals("Demo Curd")).findFirst().orElseGet(()->tenants.createIngredient(member,new IngredientRequest("Demo Curd","Dairy","kg")));var paneer=is.stream().filter(x->x.name().equals("Demo Paneer")).findFirst().orElseGet(()->tenants.createIngredient(member,new IngredientRequest("Demo Paneer","Dairy","kg")));var flour=is.stream().filter(x->x.name().equals("Demo Flour")).findFirst().orElseGet(()->tenants.createIngredient(member,new IngredientRequest("Demo Flour","Grain","kg")));if(!dairy.ingredientIds().contains(curd.id()))tenants.linkIngredient(member,UUID.fromString(dairy.id()),new SupplierIngredientRequest(UUID.fromString(curd.id()),"DEMO-CURD"));if(!dairy.ingredientIds().contains(paneer.id()))tenants.linkIngredient(member,UUID.fromString(dairy.id()),new SupplierIngredientRequest(UUID.fromString(paneer.id()),"DEMO-PANEER"));if(!farms.ingredientIds().contains(flour.id()))tenants.linkIngredient(member,UUID.fromString(farms.id()),new SupplierIngredientRequest(UUID.fromString(flour.id()),"DEMO-FLOUR"));var current=inventory.inventory(member);if(current.stream().noneMatch(x->x.lot().supplierBatchNumber().equals("DEMO-CURD-001")))inventory.receive(member,new ReceiveLotRequest(UUID.fromString(curd.id()),UUID.fromString(dairy.id()),"DEMO-CURD-001",LocalDate.now().minusDays(2),LocalDate.now().plusDays(18),UUID.fromString(kitchen.id()),new BigDecimal("20"),"kg","Synthetic demonstration stock"));if(current.stream().noneMatch(x->x.lot().supplierBatchNumber().equals("DEMO-CURD-002")))inventory.receive(member,new ReceiveLotRequest(UUID.fromString(curd.id()),UUID.fromString(dairy.id()),"DEMO-CURD-002",LocalDate.now().minusDays(1),LocalDate.now().plusDays(45),UUID.fromString(kitchen.id()),new BigDecimal("20"),"kg","Synthetic demonstration stock"));if(current.stream().noneMatch(x->x.lot().supplierBatchNumber().equals("DEMO-PANEER-001")))inventory.receive(member,new ReceiveLotRequest(UUID.fromString(paneer.id()),UUID.fromString(dairy.id()),"DEMO-PANEER-001",LocalDate.now().minusDays(1),LocalDate.now().plusDays(30),UUID.fromString(kitchen.id()),new BigDecimal("25"),"kg","Synthetic demonstration stock"));if(current.stream().noneMatch(x->x.lot().supplierBatchNumber().equals("DEMO-FLOUR-001")))inventory.receive(member,new ReceiveLotRequest(UUID.fromString(flour.id()),UUID.fromString(farms.id()),"DEMO-FLOUR-001",LocalDate.now().minusDays(3),LocalDate.now().plusDays(90),UUID.fromString(warehouse.id()),new BigDecimal("50"),"kg","Synthetic demonstration stock"));var product=products.findByOrganizationIdOrderByName(org).stream().filter(x->x.name.equals("Demo Paneer Wrap")).findFirst().orElseGet(()->{var r=production.product(member,new ProductRequest("Demo Paneer Wrap","DEMO-PW","pieces"));return products.findById(UUID.fromString(r.id())).orElseThrow();});var recipe=recipes.findByOrganizationIdOrderByCreatedAtDesc(org).stream().filter(x->x.productId.equals(product.id)).findFirst().orElseGet(()->{var r=production.createRecipe(member,new RecipeRequest(product.id,"Demo Paneer Wrap Recipe",new BigDecimal("10"),"pieces",List.of(new RecipeLineRequest(UUID.fromString(curd.id()),new BigDecimal("2"),"kg"),new RecipeLineRequest(UUID.fromString(paneer.id()),new BigDecimal("1"),"kg"))));return recipes.findById(UUID.fromString(r.id())).orElseThrow();});if(batches.findByOrganizationIdOrderByProducedAtDesc(org).stream().noneMatch(x->x.batchNumber.startsWith("DEMO-"))){var plan=production.preview(member,new ProductionPlanRequest(recipe.id,UUID.fromString(kitchen.id()),new BigDecimal("10"),"Synthetic demonstration production"));if(plan.ready())production.produceSuggested(member,new ProductionPlanRequest(recipe.id,UUID.fromString(kitchen.id()),new BigDecimal("10"),"Synthetic demonstration production"));}var demoLot=lots.findByOrganizationIdOrderByReceivedAtDesc(org).stream().filter(x->x.supplierBatchNumber.equals("DEMO-CURD-001")).findFirst().orElse(null);if(demoLot!=null&&incidentRepo.findByOrganizationIdOrderByCreatedAtDesc(org).stream().noneMatch(x->x.title.equals("Demo supplier quality concern")))incidents.create(member,new IncidentCreateRequest("Demo supplier quality concern",IncidentSeverity.HIGH,List.of(demoLot.id),"Synthetic example: supplier cold-chain evidence requested"));if(demoLot!=null&&recallRepo.findByOrganizationIdOrderByCreatedAtDesc(org).stream().noneMatch(x->x.title.equals("Demo precautionary recall")))recalls.create(member,new RecallRequest(demoLot.id,"Demo precautionary recall"));return new DemoSeedResponse("Demo data loaded",tenants.locations(member).size(),tenants.suppliers(member).size(),tenants.ingredients(member).size(),inventory.inventory(member).size(),recipes.findByOrganizationIdOrderByCreatedAtDesc(org).size(),batches.findByOrganizationIdOrderByProducedAtDesc(org).size(),incidentRepo.findByOrganizationIdOrderByCreatedAtDesc(org).size(),recallRepo.findByOrganizationIdOrderByCreatedAtDesc(org).size());}
}
